package com.campusiq.platform.strategy; import com.campusiq.platform.client.*; import org.junit.jupiter.api.Test; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; class StrategyMappingTest {@Test void leetcodeRejectsInvalidPayloadAndMapsData(){var c=mock(LeetCodeClient.class);when(c.profile("bad")).thenReturn(new LeetCodeClient.Profile(null,null,null,null,null,"user not found"));assertThat(new LeetCodeStrategy(c).verifyUser("bad")).isFalse();when(c.profile("ok")).thenReturn(new LeetCodeClient.Profile("ok","Ada","avatar",11L,7L,null));when(c.solved("ok")).thenReturn(new LeetCodeClient.Solved(10,2,3,5));when(c.contest("ok")).thenReturn(new LeetCodeClient.Contest(1500.0,99L,4.2));var p=new LeetCodeStrategy(c).fetchProfile("ok");assertThat(p.totalSolved()).isEqualTo(10);assertThat(p.contestRanking()).isEqualTo(99L);}@Test void codeforcesCountsUniqueAcceptedAndMapsMaxRating(){var c=mock(CodeforcesClient.class);when(c.info("ada")).thenReturn(new CodeforcesClient.InfoResponse("OK",List.of(new CodeforcesClient.UserInfo("ada","Ada",null,1600L,"expert",3L,1900L)),null));when(c.status("ada")).thenReturn(new CodeforcesClient.StatusResponse("OK",List.of(new CodeforcesClient.Submission("OK",1L,new CodeforcesClient.Problem("A")),new CodeforcesClient.Submission("OK",1L,new CodeforcesClient.Problem("A"))),null));var p=new CodeforcesStrategy(c).fetchProfile("ada");assertThat(p.totalSolved()).isEqualTo(1);assertThat(p.maxRating()).isEqualTo(1900d);}}
